import { randomUUID as randomUUID8 } from "node:crypto";
var FIRST_COMPANY_NAME = "KIT audiovisual";
async function requireHuman(config, token) {
  if (!config.recaptchaVerifier) return;
  let human = false;
  try {
    human = Boolean(token) && await config.recaptchaVerifier(token, "LOGIN");
  } catch {
  }
  if (!human) throw new HttpError(403, "The security check failed. Try again.");
}
function mountAuthRoutes(app, { repo, config }) {
  app.get(
    "/api/health",
    async (_req, res) => res.json({ ok: true, initialized: await repo.initialized() })
  );
  app.get(
    "/api/session",
    async (_req, res) => res.json({
      initialized: await repo.initialized(),
      user: res.locals.user || null,
      csrf: res.locals.csrf || null
    })
  );
  app.post("/api/setup", async (req, res) => {
    await rateLimit(repo, `setup:${req.ip}`, 10);
    if (await repo.initialized())
      throw new HttpError(
        409,
        "This workspace is already configured. Sign in instead."
      );
    const input = setupSchema.parse(req.body);
    const encoded = await passwordHash(input.password);
    const id3 = randomUUID8();
    await repo.transaction(async () => {
      if (await repo.initialized())
        throw new HttpError(409, "Workspace setup was already completed.");
      await repo.db.prepare(
        "INSERT INTO users (id,email,name,role,owner,password_hash) VALUES (?,?,?,?,1,?)"
      ).run(id3, input.email, input.name, "Administrator", encoded);
      await repo.db.prepare("INSERT INTO workspace VALUES (1,0,?)").run(JSON.stringify(emptyWorkspace(input.company)));
      await repo.audit(id3, "Company workspace created", input.company);
    });
    const csrf = await createSession(repo, id3, res, Boolean(config.secureCookies));
    res.status(201).json({ user: publicUser(await repo.user(id3)), csrf });
  });
  app.post("/api/login", async (req, res) => {
    const input = loginSchema.parse(req.body);
    await rateLimit(repo, `login:${req.ip}`);
    await requireHuman(config, input.recaptchaToken);
    const row = await repo.userByEmail(input.email);
    const decoyHash = "f".repeat(48) + ":" + "0".repeat(128);
    const matches = await passwordMatches(
      input.password,
      row?.password_hash || decoyHash
    );
    if (!row?.active || !matches)
      throw new HttpError(401, "Email or password is incorrect.");
    await destroySession(repo, req, res, Boolean(config.secureCookies));
    const csrf = await createSession(
      repo,
      row.id,
      res,
      Boolean(config.secureCookies)
    );
    await repo.audit(row.id, "User signed in", row.email);
    res.json({ user: publicUser(row), csrf });
  });
  app.post("/api/login/supabase", async (req, res) => {
    if (!config.supabaseVerifier)
      throw new HttpError(404, "Portal sign-in is not configured.");
    await rateLimit(repo, `login:${req.ip}`);
    const { accessToken } = supabaseLoginSchema.parse(req.body);
    let identity;
    try {
      identity = await config.supabaseVerifier(accessToken);
    } catch {
      throw new HttpError(401, "The sign-in could not be verified.");
    }
    if (!identity.emailVerified || identity.portalRole !== "admin" || identity.accountStatus !== "active")
      throw new HttpError(
        401,
        "This account does not have access to the workspace."
      );
    if (!await repo.initialized()) {
      await repo.transaction(async () => {
        if (await repo.initialized()) return;
        const owner = await repo.upsertFederatedUser({
          id: randomUUID8(),
          email: identity.email,
          name: identity.name || identity.email,
          role: "Administrator",
          isOwner: true,
          eventIds: [],
          sharedProposalIds: []
        });
        await repo.db.prepare("INSERT INTO workspace VALUES (1,0,?)").run(JSON.stringify(emptyWorkspace(FIRST_COMPANY_NAME)));
        await repo.audit(
          owner.id,
          "Company workspace created",
          `${FIRST_COMPANY_NAME} \xB7 first portal administrator`
        );
      });
    }
    let row = await repo.userByEmail(identity.email);
    if (row && !row.active)
      throw new HttpError(
        401,
        "This account does not have access to the workspace."
      );
    row ??= await repo.upsertFederatedUser({
      id: randomUUID8(),
      email: identity.email,
      name: identity.name || identity.email,
      role: "Administrator",
      isOwner: false,
      eventIds: [],
      sharedProposalIds: []
    });
    await destroySession(repo, req, res, Boolean(config.secureCookies));
    const csrf = await createSession(
      repo,
      row.id,
      res,
      Boolean(config.secureCookies)
    );
    await repo.audit(row.id, "User signed in with the portal", row.email);
    res.json({ user: publicUser(row), csrf });
  });
  app.post("/api/logout", async (req, res) => {
    await destroySession(repo, req, res, Boolean(config.secureCookies));
    res.json({ ok: true });
  });
}

// server/routes/workspace.ts
function mountWorkspaceRoutes(app, { repo, response }) {
  app.get("/api/workspace", async (_req, res) => res.json(await response(res)));
  app.patch("/api/workspace", async (req, res) => {
    const user = userOf(res);
    const input = changeSchema.parse(req.body);
    await repo.transaction(async () => {
      const current = await repo.read();
      if (input.revision !== current.revision)
        throw new HttpError(
          409,
          "Another session changed this workspace. Reload the latest data before saving."
        );
      const next = applyChanges(current.workspace, input.changes, user);
      for (const change of input.changes.filter(
        (c) => c.collection === "tasks"
      )) {
        const task = next.tasks.find((t) => t.id === change.id);
        if (task.assigneeId) {
          const assignee = await repo.user(task.assigneeId);
          if (!assignee?.active || assignee.role === "Client / Guest" || assignee.role !== "Administrator" && !JSON.parse(assignee.event_ids).includes(task.eventId) || assignee.name !== task.assignee)
            throw new HttpError(
              422,
              "La persona asignada debe tener una cuenta activa y acceso al evento."
            );
        }
      }
      for (const change of input.changes.filter(
        (c) => c.collection === "operations"
      )) {
        const operation = next.operations.find(
          (item2) => item2.id === change.id
        );
        for (const shift of operation.crewShifts) {
          if (!shift.memberId) continue;
          const member = await repo.user(shift.memberId);
          if (!member?.active || member.role === "Client / Guest" || member.role !== "Administrator" && !JSON.parse(member.event_ids).includes(operation.eventId) || member.name !== shift.person)
            throw new HttpError(
              422,
              "La persona del turno debe tener una cuenta activa y acceso al evento."
            );
        }
      }
      await repo.save(next, input.revision);
      for (const c of input.changes) {
        const eventId = c.collection === "events" ? c.id : typeof c.value === "object" && c.value && "eventId" in c.value ? String(c.value.eventId) : void 0;
        await repo.audit(
          user.id,
          `${c.collection} record saved`,
          `${user.name} \xB7 ${c.id}`,
          eventId
        );
      }
    });
    res.json(await response(res));
  });
}

// server/routes/conversations.ts
import { z as z8 } from "zod";
function mountConversationRoutes(app, { repo, response }) {
  app.post("/api/conversations/:id/accept", async (req, res) => {
    const user = userOf(res);
    if (!user.isOwner)
      throw new HttpError(403, "Only the owner can confirm client acceptance.");
    const revision = z8.object({ revision: z8.number().int().nonnegative() }).strict().parse(req.body).revision;
    await repo.transaction(async () => {
      const current = await repo.read();
      if (revision !== current.revision)
        throw new HttpError(
          409,
          "The offer or conversation changed. Reload it before confirming."
        );
      const next = acceptConversation(current.workspace, String(req.params.id));
      const confirmed = next.conversations.find(
        (conversation2) => conversation2.id === req.params.id
      );
      if (confirmed?.acceptanceEvidence)
        confirmed.acceptanceEvidence.ownerId = user.id;
      await repo.save(next, revision);
      const conversation = next.conversations.find(
        (c) => c.id === req.params.id
      );
      await repo.audit(
        user.id,
        "Owner confirmed client acceptance",
        `${user.name} \xB7 ${conversation.proposalId} \xB7 revision ${conversation.proposalVersion}`,
        conversation.eventId
      );
    });
    res.json(await response(res));
  });
}

