// server/supabase-auth.ts
function supabaseVerifier(url, publishableKey) {
  const base = url.replace(/\/+$/, "");
  const get = async (path, token) => {
    const response = await fetch(`${base}${path}`, {
      headers: {
        apikey: publishableKey,
        Authorization: `Bearer ${token}`,
        Accept: "application/json"
      },
      signal: AbortSignal.timeout(8e3)
    });
    if (!response.ok) throw new Error(`supabase ${response.status}`);
    return response.json();
  };
  return async (accessToken) => {
    const user = await get("/auth/v1/user", accessToken);
    if (!user.id || !user.email) throw new Error("no user");
    const id3 = encodeURIComponent(user.id);
    const profiles = await get(
      `/rest/v1/profiles?id=eq.${id3}&select=role,account_status,full_name`,
      accessToken
    );
    return {
      email: user.email,
      emailVerified: Boolean(user.email_confirmed_at),
      portalRole: profiles[0]?.role ?? "user",
      accountStatus: profiles[0]?.account_status ?? "unknown",
      name: profiles[0]?.full_name || void 0
    };
  };
}

// server/recaptcha.ts
function recaptchaVerifier(projectId, apiKey, siteKey, minScore = 0.5) {
  return async (token, action) => {
    const response = await fetch(
      `https://recaptchaenterprise.googleapis.com/v1/projects/${encodeURIComponent(projectId)}/assessments?key=${encodeURIComponent(apiKey)}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          event: { token, siteKey, expectedAction: action }
        })
      }
    );
    if (!response.ok) return false;
    const result2 = await response.json();
    return result2.tokenProperties?.valid === true && result2.tokenProperties.action === action && (result2.riskAnalysis?.score ?? 0) >= minScore;
  };
}

// server/bootstrap.ts
function configFromEnv(env, defaultOrigins) {
  const integrations = integrationsFromEnv(env);
  const ai = integrations.ai;
  return {
    logger: jsonLogger(parseLogLevel(env.KIT_LOG_LEVEL)),
    integrations,
    supabaseVerifier: env.SUPABASE_URL && env.SUPABASE_PUBLISHABLE_KEY ? supabaseVerifier(env.SUPABASE_URL, env.SUPABASE_PUBLISHABLE_KEY) : void 0,
    recaptchaVerifier: env.RECAPTCHA_PROJECT_ID && env.RECAPTCHA_API_KEY && env.RECAPTCHA_SITE_KEY ? recaptchaVerifier(
      env.RECAPTCHA_PROJECT_ID,
      env.RECAPTCHA_API_KEY,
      env.RECAPTCHA_SITE_KEY
    ) : void 0,
    design: designFromEnv(env, ai),
    kitGenerator: ai?.chatModel ? aiKitGenerator(ai.provider, ai.key, ai.chatModel) : void 0,
    search: {
      name: env.KIT_SEARCH_PROVIDER_NAME || "No configurado",
      providerIdentity: env.KIT_SEARCH_PROVIDER_URL || "",
      region: env.KIT_SEARCH_REGION || "",
      retention: env.KIT_SEARCH_RETENTION || "",
      monthlyBudgetCents: Number(env.KIT_SEARCH_MONTHLY_BUDGET_CENTS || 0),
      embeddingCentsPerThousandCharacters: Number(
        env.KIT_SEARCH_CENTS_PER_1000_CHARS || 0
      ),
      encryptionKey: env.KIT_SEARCH_ENCRYPTION_KEY ? Buffer.from(env.KIT_SEARCH_ENCRYPTION_KEY, "hex") : void 0,
      provider: env.KIT_SEARCH_PROVIDER_URL && env.KIT_SEARCH_PROVIDER_TOKEN ? httpSearchProvider(
        env.KIT_SEARCH_PROVIDER_URL,
        env.KIT_SEARCH_PROVIDER_TOKEN
      ) : void 0
    },
    proposalGenerator: ai?.proposalModel ? aiProposalGenerator(ai.provider, ai.key, ai.proposalModel) : void 0,
    origins: (env.KIT_ORIGINS || defaultOrigins).split(","),
    secureCookies: env.KIT_SECURE_COOKIES === "true",
    cronSecret: env.CRON_SECRET || void 0
  };
}
function designFromEnv(env, ai) {
  const higgsfieldKey = env.HIGGSFIELD_API_KEY?.trim() || (env.HIGGSFIELD_KEY_ID && env.HIGGSFIELD_KEY_SECRET ? `${env.HIGGSFIELD_KEY_ID.trim()}:${env.HIGGSFIELD_KEY_SECRET.trim()}` : "");
  const cap = Number(env.KIT_DESIGN_MONTHLY_RENDER_CAP || 100);
  const videoCap = Number(env.KIT_DESIGN_MONTHLY_VIDEO_CAP || 10);
  return {
    designer: ai?.planModel ? aiDesigner(ai.provider, ai.key, ai.planModel) : void 0,
    renderer: higgsfieldKey ? higgsfieldRenderProvider({
      key: higgsfieldKey,
      ...env.KIT_DESIGN_RENDER_MODEL?.trim() ? { model: env.KIT_DESIGN_RENDER_MODEL.trim() } : {}
    }) : void 0,
    videoRenderer: higgsfieldKey ? higgsfieldVideoProvider({
      key: higgsfieldKey,
      ...env.KIT_DESIGN_VIDEO_MODEL?.trim() ? { model: env.KIT_DESIGN_VIDEO_MODEL.trim() } : {},
      ...Number(env.KIT_DESIGN_VIDEO_SECONDS) ? { seconds: Number(env.KIT_DESIGN_VIDEO_SECONDS) } : {}
    }) : void 0,
    storage: env.SUPABASE_URL && env.SUPABASE_SECRET_KEY ? supabaseStorage(env.SUPABASE_URL, env.SUPABASE_SECRET_KEY) : void 0,
    monthlyRenderCap: Number.isFinite(cap) && cap >= 0 ? cap : 100,
    monthlyVideoCap: Number.isFinite(videoCap) && videoCap >= 0 ? videoCap : 10
  };
}

// server/vercel-entry.ts
var starting;
async function start() {
  const url = process.env.KIT_DATABASE;
  if (!url || !/^postgres(ql)?:\/\//i.test(url))
    throw new NotConfigured(
      "KIT_DATABASE must be the Postgres connection string in this environment."
    );
  const repo = await Repository.open(url);
  const app = createApp(repo, {
    ...configFromEnv(process.env, "http://127.0.0.1:5173"),
    // The CDN serves the built frontend; Express only answers /api.
    serveStatic: false,
    // One proxy hop (Vercel) sits in front, so req.ip is the real client for rate limits.
    trustProxy: 1,
    // A new instance says nothing about AI jobs running on other instances.
    resetBusyOnBoot: false
  });
  await app.locals.ready;
  return app;
}
var NotConfigured = class extends Error {
};
async function handler(req, res) {
  try {
    starting ??= start();
    const app = await starting;
    app(req, res);
  } catch (error) {
    starting = void 0;
    console.error(
      JSON.stringify({
        level: "error",
        msg: "kit_start_failed",
        error: error instanceof Error ? error.name : "Unknown error"
      })
    );
    res.statusCode = 503;
    res.setHeader("Content-Type", "application/json");
    res.setHeader("Cache-Control", "no-store");
    res.end(
      JSON.stringify({
        error: error instanceof NotConfigured ? "The company database is not configured for this deployment." : "The company server could not start. Try again in a moment."
      })
    );
  }
}
export {
  handler as default
};
